async function showVehicles() {
  const res = await fetch("/api/vehicles");
  const vehicles = await res.json();

  const list = document.querySelector("#vehicleList");
  const frag = document.createDocumentFragment();
  vehicles.forEach(v => {
    const li = document.createElement("li");
    li.textContent = v.number + " (" + v.type + ")";
    frag.appendChild(li);
  });
  list.replaceChildren(frag);
}

/* Use border-box everywhere */
*, *::before, *::after {
  box-sizing: border-box;
}

.card {
  width: 200px;
  padding: 20px;          /* inside the border */
  border: 1px solid #ddd;
  margin: 16px auto;      /* outside; auto centres horizontally */
}
/* content-box: total width = 200 + 40 + 2 = 242px
   border-box:  total width = 200px (content shrinks to 158px) */

/* Flexbox: navbar with logo left and links right */
.navbar {
  display: flex;
  justify-content: space-between;   /* main axis */
  align-items: center;              /* cross axis */
  gap: 16px;
}

/* Flexbox: perfectly centre anything */
.center {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

/* Grid: responsive card grid, no media queries needed */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
}

/* Grid: page layout */
.page {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-rows: 60px 1fr;
  grid-template-areas: "side top" "side main";
}

.card {
  position: relative;          /* reference for the badge */
}
.card .badge {
  position: absolute;          /* corner of the card */
  top: 8px;
  right: 8px;
}

.chat-button {
  position: fixed;             /* always bottom-right of the window */
  right: 20px;
  bottom: 20px;
  z-index: 100;
}

thead th {
  position: sticky;            /* table header stays visible */
  top: 0;
  background: white;
}
